--- README.md ---
# Team fastcsv parser

Maintained local fork, version 1.4.0. Counts ordinary comma-separated records without quote handling.
--- fastcsv.c ---
#include "fastcsv.h"

int fastcsv_count_fields(const char *line) {
    if (line == 0 || *line == '\0') {
        return 0;
    }
    int fields = 1;
    for (const char *p = line; *p != '\0'; ++p) {
        if (*p == ',') {
            ++fields;
        }
    }
    return fields;
}
